+func TestConfigReadErrors(t *testing.T) {
+	t.Run("missing", func(t *testing.T) {
+		got := checkConfig(t.TempDir())
+		want := Check{"config", "fail", ".kogen/project.yaml is missing", "in your project, run kogen init"}
+		if got != want {
+			t.Fatalf("got %+v, want %+v", got, want)
+		}
+	})
+	t.Run("directory", func(t *testing.T) {
+		root := t.TempDir()
+		if err := os.MkdirAll(filepath.Join(root, project.ConfigPath), 0755); err != nil {
+			t.Fatal(err)
+		}
+		got := checkConfig(root)
+		if got.Status != "fail" || !strings.Contains(got.Detail, project.ConfigPath) || !strings.Contains(got.Detail, "directory") || strings.Contains(got.Detail, "missing") || strings.Contains(got.Fix, "kogen init") || !strings.Contains(got.Fix, "file") {
+			t.Fatalf("existing directory report: %+v", got)
+		}
+	})
+	t.Run("valid", func(t *testing.T) {
+		root := t.TempDir()
+		writeProjectFile(t, root, project.ConfigPath, "version: 1\n")
+		got := checkConfig(root)
+		want := Check{"config", "ok", ".kogen/project.yaml is valid", ""}
+		if got != want {
+			t.Fatalf("got %+v, want %+v", got, want)
+		}
+	})
+	t.Run("malformed", func(t *testing.T) {
+		root := t.TempDir()
+		writeProjectFile(t, root, project.ConfigPath, "version: 1\ncommands: [\n")
+		got := checkConfig(root)
+		want := Check{"config", "fail", "line 2: unclosed [", "edit .kogen/project.yaml at line 2"}
+		if got != want {
+			t.Fatalf("got %+v, want %+v", got, want)
+		}
+	})
+}

